interface Service {
  fetch(): string
}
class RealService implements Service {
  fetch() { return 'data' }
}
class ServiceProxy implements Service {
  private real?: RealService
  fetch() {
    if (!this.real) this.real = new RealService()
    return this.real.fetch()
  }
}
const s: Service = new ServiceProxy()
s.fetch()

interface Logger {
  log(msg: string): void
}
class ConsoleLogger implements Logger {
  log(msg: string) { console.log(msg) }
}
class LoggerProxy implements Logger {
  constructor(private logger: Logger) {}
  log(msg: string) {
    const stamped = `[${new Date().toISOString()}] ${msg}`
    this.logger.log(stamped)
  }
}
const logger = new LoggerProxy(new ConsoleLogger())
logger.log('hi')

interface DataFetcher {
  fetch(): Promise<string>
}
class RealFetcher implements DataFetcher {
  async fetch() { return 'payload' }
}
// Version A: subclassing
class FetcherSubclass extends RealFetcher {
  private cached?: Promise<string>
  private hasAccess() { return true }
  async fetch() {
    if (!this.hasAccess()) throw new Error('denied')
    if (!this.cached) this.cached = super.fetch()
    return this.cached
  }
}
// Version B: delegation via wrapper
class FetcherProxy implements DataFetcher {
  private cached?: Promise<string>
  constructor(private real: DataFetcher) {}
  private hasAccess() { return true }
  async fetch() {
    if (!this.hasAccess()) throw new Error('denied')
    if (!this.cached) this.cached = this.real.fetch()
    return this.cached
  }
}
